        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Bolivia, celle a pagamento",
        "testo_it": "Bolivia: nel sovraffollato carcere di San Pedro a La Paz, i detenuti gestiscono le celle a pagamento.",
        "priorita": "Bassa",
